// Thresholds set against the REAL rating distribution (floor 72,
// median 79, ceiling 92). Verified spread across 651 players:
//   elite    87+  ~4%   -- genuinely rare
//   platinum 83+  ~15%
//   forest   79+  ~31%
//   midnight 75+  ~31%
//   sand     rest ~19%
// Deliberately top-heavy rather than an even quota: these are Premier
// League footballers, so only a minority should sit in the bottom tier.
//
// Special editions are checked FIRST and override the rating tier
// entirely. Both need a real rating as well as the age condition --
// without that, every teenage academy squad-filler would get a
// wonderkid card and the whole thing would stop meaning anything.
function tierFor(rating, age) {
  const r = rating || 0;

  // Under 21 and already performing at a decent level.
  if (age && age <= 21 && r >= 79) return TIERS.wonderkid;
  // Still going strong at an age where most have declined.
  if (age && age >= 32 && r >= 81) return TIERS.veteran;

  if (r >= 87) return TIERS.elite;
  if (r >= 83) return TIERS.platinum;
  if (r >= 79) return TIERS.forest;
  if (r >= 75) return TIERS.midnight;
  return TIERS.sand;
}


// Real flags, rendered natively by the OS. A two-letter country code
// maps directly onto regional indicator symbols, so every ISO country
// works automatically and accurately -- no hand-drawn approximations,
// and no 91 base64 images to ship. England and Wales aren't ISO
// countries (they're UK subdivisions), so they use the separate emoji
// tag-sequence form instead.
const FLAG_TAG_SEQUENCES = {
  EN: '\u{1F3F4}\u{E0067}\u{E0062}\u{E0065}\u{E006E}\u{E0067}\u{E007F}', // England
  WA: '\u{1F3F4}\u{E0067}\u{E0062}\u{E0077}\u{E006C}\u{E0073}\u{E007F}', // Wales
  SCT: '\u{1F3F4}\u{E0067}\u{E0062}\u{E0073}\u{E0063}\u{E0074}\u{E007F}', // Scotland
};

function flagEmoji(code) {
  if (!code) return '';
  const cc = String(code).toUpperCase();
  if (FLAG_TAG_SEQUENCES[cc]) return FLAG_TAG_SEQUENCES[cc];
  if (cc.length !== 2) return '';
  return cc.replace(/./g, (c) => String.fromCodePoint(127397 + c.charCodeAt(0)));
}

function initialsFor(name) {
  const parts = (name || '').trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return '?';
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

